// Configuración de reglas
const ROAS_OBJETIVO = 3;       // ROAS mínimo para escalar (300%)
const AUMENTO_PORCENT = 0.20;  // Aumentar presupuesto un 20%
const MAX_PRESUPUESTO = 50000; // Tope máximo en ARS

const resultados = [];

for (const item of $input.all()) {
  const body = item.json;
  const rows = body[0]?.results || [];

  for (const row of rows) {
    const campaign = row.campaign;
    const budget = row.campaignBudget;
    const metrics = row.metrics;

    const gasto = (metrics.costMicros || 0) / 1_000_000;
    const conversiones = metrics.conversions || 0;
    const valorConversiones = metrics.conversionsValue || 0;

    // Calcular ROAS
    const roas = gasto > 0 ? valorConversiones / gasto : 0;
    const presupuestoActual = (budget?.amountMicros || 0) / 1_000_000;
    const nuevoPres = presupuestoActual * (1 + AUMENTO_PORCENT);

    const accion = (() => {
      if (gasto === 0) return 'SIN_GASTO';
      if (roas >= ROAS_OBJETIVO && nuevoPres <= MAX_PRESUPUESTO) return 'ESCALAR';
      if (roas >= ROAS_OBJETIVO && nuevoPres > MAX_PRESUPUESTO) return 'EN_TOPE';
      if (roas < 1 && gasto > 3000) return 'REVISAR';
      return 'OK';
    })();

    resultados.push({
      json: {
        campaignId: campaign.id,
        campaignName: campaign.name,
        budgetResourceName: budget?.resourceName,
        gasto: gasto.toFixed(2),
        valorConversiones: valorConversiones.toFixed(2),
        conversiones: conversiones,
        roas: roas.toFixed(2),
        presupuestoActual: presupuestoActual.toFixed(2),
        nuevoPresupuesto: nuevoPres.toFixed(2),
        nuevoPres_micros: Math.round(nuevoPres * 1_000_000),
        accion
      }
    });
  }
}

return resultados.length > 0 ? resultados : [{ json: { accion: 'SIN_DATOS' } }];
